let me=null,catalog=[],currentPage='home',selectedGroup='',selectedSubject='all',periodKind='month',chartType='table',sequence=0,currentRecords=[],people=[],directory=[],activeChat='',chatBefore=null,chatTimer=null,roleChoice='student',pendingInvite=new URLSearchParams(location.search).get('invite')||'',pollResults={},helpDraft='';
