const date=d=>d?new Date(d.length===10?d+'T12:00:00Z':d).toLocaleString('ru-RU',d.length===10?{day:'numeric',month:'short',year:'numeric'}:{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
