function opts(items,value){return items.map(([v,t])=>'<option value="'+esc(v)+'" '+(String(v)===String(value)?'selected':'')+'>'+esc(t)+'</option>').join('');}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500);}
async function api(path,method='GET',data){return DemoAPI.call(path,method,data||{});}
function panel(title,sub,content,action=''){return'<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><div class="panel-sub">'+sub+'</div></div>'+action+'</div><div class="panel-body">'+content+'</div></section>';}
function empty(text){return'<div class="empty school-empty"><span>✧</span><p>'+text+'</p></div>';}
function button(label,id,primary=false){return'<button class="button '+(primary?'primary':'')+'" id="'+id+'">'+label+'</button>';}
function field(label,name,value='',type='text',attr=''){return'<label class="stack-label">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+attr+'></label>';}
function select(label,name,items,value='',attr=''){return'<label class="stack-label">'+label+'<select name="'+name+'" '+attr+'>'+opts(items,value)+'</select></label>';}
function textarea(label,name,value='',attr=''){return'<label class="stack-label full-field">'+label+'<textarea name="'+name+'" rows="4" maxlength="12000" '+attr+'>'+esc(value)+'</textarea></label>';}
function filesInput(){return'<label class="stack-label full-field">Вложения: PDF, изображения, TXT, DOCX · до 250 КБ каждый<input name="files" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.docx"></label>';}
function attachments(r){return (r.attachments||[]).map(a=>'<a class="attachment" href="'+esc(DemoAPI.fileURL(a.id))+'" download="'+esc(a.filename)+'" target="_blank" rel="noopener">↓ '+esc(a.filename)+'</a>').join('');}
function prefs(){const p=me?.user?.profile||{};document.documentElement.dataset.theme=p.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):p.theme||'light';document.documentElement.dataset.accent=p.accent||'forest';document.documentElement.dataset.motion=p.motion===false?'off':'on';}
function avatar(){const p=me?.user?.profile||{};return'<span class="avatar">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="Аватар">':esc(p.avatar||'✦'))+'</span>';}
function goto(page){if(location.hash.slice(1)===page)render();else location.hash=page;}
async function auth(){const ticket=++sequence;$('#content').innerHTML='<div class="loading">Проверяем сеанс…</div>';try{const next=await api('/me');if(ticket!==sequence)return;me=next;prefs();$('#logout').hidden=!next.authenticated;$('#nav').innerHTML='';if(!next.authenticated||next.sessionRequired){loginView(next);return;}catalog=(await api('/catalog')).institutions;if(ticket!==sequence)return;if(!active()){await registrationView();return;}if(!groups().some(g=>g.id===selectedGroup))selectedGroup=groups()[0]?.id||'';await render();if(!me.user.profile.tutorial_done&&!$('#modal').open){await api('/profile','PATCH',{tutorial_done:true});me.user.profile.tutorial_done=true;showTutorial();}}catch(e){showError(e.message,auth);}}
function loginView(state){demoLoginView(state);}
function showError(message,retry=render){$('#content').innerHTML='<div class="callout warning"><b>Не удалось загрузить раздел</b><p>'+esc(message)+'</p>'+button('Попробовать снова','retry')+'</div>';$('#retry').onclick=retry;}
async function safely(fn){try{await fn()}catch(e){toast(e.message);const feedback=$('#form-error');if(feedback)feedback.textContent=e.message;}}
function modal(title,html){$('#modal-body').innerHTML='<h2>'+title+'</h2>'+html;$('#modal').showModal();}
function formModal(title,html,onSubmit){modal(title,'<form id="main-form" class="record-form">'+html+'<div id="form-error" class="form-feedback full-field" role="alert"></div><div class="modal-actions full-field"><button class="button" type="button" id="form-cancel">Отмена</button><button class="button primary" type="submit">Сохранить</button></div></form>');$('#form-cancel').onclick=()=>$('#modal').close();$('#main-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Сохраняем…';try{await onSubmit(Object.fromEntries(new FormData(e.target)),e.target);$('#modal').close();toast('Сохранено');await auth();}catch(err){$('#form-error').textContent=err.message;submit.disabled=false;submit.textContent='Сохранить';}};}
async function uploadFiles(form){const chosen=[...(form.querySelector('[name=files]')?.files||[])];if(chosen.length>5)throw Error('Не более пяти вложений');const ids=[];for(const file of chosen){if(file.size>250*1024)throw Error('Файл '+file.name+' больше 250 КБ');const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Не удалось прочитать файл'));r.readAsDataURL(file)});const out=await api('/uploads','POST',{filename:file.name,mime:file.type,base64:encoded});ids.push(out.id);}return ids;}
async function registrationView(){const apps=me.applications||[],pending=apps.find(a=>a.status==='pending'),approved=apps.find(a=>a.status==='approved');$('#page-title').textContent=pending?'Заявка на рассмотрении':'Настроим ваш доступ';$('#role-label').textContent='РЕГИСТРАЦИЯ В УЧРЕЖДЕНИИ';if(pending||approved&&me.membership?.status!=='active'){$('#content').innerHTML=panel('Профиль сохранён',esc(me.user.name),'<div class="callout">'+(pending?'Доступ ожидает подтверждения уполномоченным сотрудником. Выбор роли сам по себе не даёт прав.':'Заявка обработана. Проверьте статус доступа.')+'</div>'+button('Проверить статус','check-status')+'<form id="join-pending" class="inline-form"><label class="stack-label">Есть приглашение?<input name="code" placeholder="Код приглашения" required></label><button class="button primary">Применить код</button></form>');$('#check-status').onclick=auth;$('#join-pending').onsubmit=e=>{e.preventDefault();safely(async()=>{await api('/join','POST',{code:new FormData(e.target).get('code')});await auth()});};return;}
$('#content').innerHTML='<div class="role-choice"><button class="role-card '+(roleChoice==='student'?'selected':'')+'" data-reg-role="student"><span>✧</span><b>Ученик</b><p>Оценки, задания, общение</p></button><button class="role-card '+(roleChoice==='teacher'?'selected':'')+'" data-reg-role="teacher"><span>✦</span><b>Учитель</b><p>Мои предметы и группы</p></button><button class="role-card '+(roleChoice==='other'?'selected':'')+'" data-reg-role="other"><span>⌂</span><b>Другое</b><p>Директор или завуч</p></button></div>'+panel('Заявка на доступ','Анкета сохраняется в вашей учётной записи','<form id="register-form" class="record-form">'+field('ФИО','name',me.user.name,'text','required maxlength="120"')+select('Тип учреждения','type',[['school','Школа'],['college','Колледж'],['university','Университет']])+'<div id="institution-field"></div><div id="level-field"></div>'+(roleChoice==='other'?select('Должность','job',[['director','Директор'],['deputy','Завуч']])+'<label class="check-label"><input name="teaches" type="checkbox">Также преподаю</label>':'')+'<div class="full-field" id="group-field"></div><div class="full-field" id="subjects-field"></div>'+field('Код приглашения (если есть)','invite',pendingInvite,'text','maxlength="100"')+'<p class="small-note full-field">Ученику потребуется подтверждение вступления в группу. Права учителя и руководства выдаются после проверки заявки или принятия приглашения.</p><div id="registration-error" class="form-feedback full-field" role="alert"></div><button class="button primary" type="submit">Подать заявку</button></form>')+(me.platformOwner?'<div class="callout section-gap">Первое учреждение ещё не настроено? Только владелец проекта может выполнить первичную настройку. '+button('Создать учреждение','bootstrap')+'</div>':'');
document.querySelectorAll('[data-reg-role]').forEach(b=>b.onclick=()=>{roleChoice=b.dataset.regRole;registrationView();});if($('#bootstrap'))$('#bootstrap').onclick=createInstitution;const form=$('#register-form');form.elements.type.onchange=()=>refreshInstitutions(form);form.elements.teaches?.addEventListener('change',()=>refreshGroups(form));form.onsubmit=e=>{e.preventDefault();safely(async()=>{const b=Object.fromEntries(new FormData(form));b.role=roleChoice==='other'?b.job:roleChoice;b.teaches=roleChoice==='teacher'||!!b.teaches;b.groups=[...form.querySelectorAll('[name=groups]:checked')].map(x=>x.value);b.subjects=(b.subjects||'').split(',').map(x=>x.trim()).filter(Boolean);await api('/register','POST',b);pendingInvite='';await auth();});};await refreshInstitutions(form);}
async function refreshInstitutions(form){const list=catalog.filter(i=>i.type===form.elements.type.value);$('#institution-field').innerHTML=select('Название учреждения','institution_id',list.length?[['','Выберите учреждение'],...list.map(i=>[i.id,i.name])]:[['','Учреждения пока нет']]);form.elements.institution_id.onchange=()=>refreshGroups(form);$('#level-field').innerHTML='';$('#group-field').innerHTML='';$('#subjects-field').innerHTML='';}
async function refreshGroups(form){const inst=catalog.find(i=>i.id===form.elements.institution_id.value);if(!inst)return;const unit=inst.type==='school'?'Класс':'Курс';const oldLevel=form.elements.level?.value||1;$('#level-field').innerHTML=select(unit,'level',Array.from({length:inst.config.max_level},(_,i)=>[i+1,(i+1)+' '+unit.toLowerCase()]),oldLevel);const res=await api('/catalog/groups?institution_id='+inst.id);const update=()=>{const list=roleChoice==='student'?res.groups.filter(g=>g.level===Number(form.elements.level.value)):res.groups;$('#group-field').innerHTML='<div class="settings-label">'+(inst.type==='school'?'Классы':'Группы')+'</div><div class="check-grid">'+(list.length?list.map(g=>'<label class="check-label"><input name="groups" type="checkbox" value="'+esc(g.id)+'">'+esc(g.name)+' · '+g.level+' '+unit.toLowerCase()+'</label>').join(''):'<p class="small-note">Группы ещё не созданы администрацией.</p>')+'</div>';const teaching=roleChoice==='teacher'||roleChoice==='other'&&form.elements.teaches.checked;$('#subjects-field').innerHTML=teaching?field('Преподаваемые предметы через запятую','subjects','','text','required placeholder="Математика, Информатика"'):'';};form.elements.level.onchange=update;update();}
function createInstitution(){formModal('Первичная настройка учреждения',field('Название учреждения','name','','text','required')+select('Тип учреждения','type',[['school','Школа'],['college','Колледж'],['university','Университет']])+field('Число курсов для колледжа / университета','max_level',4,'number','min="1" max="11"')+select('Шкала оценивания','scale',[[5,'5 баллов'],[10,'10 баллов'],[100,'100 баллов']])+field('Начало учебного года','year_start','2026-09-01','date')+field('Конец учебного года','year_end','2027-08-31','date')+field('Начало четверти / семестра','term_start','2026-09-01','date')+field('Конец четверти / семестра','term_end','2026-12-31','date')+'<p class="small-note full-field">Действие доступно только владельцу проекта. Учреждение создаётся без вымышленных учеников и сотрудников.</p>',b=>api('/institutions','POST',b));}
function allowedPages(){const out=['home','grades','schedule','homework','remarks','ranking','announcements','chats','achievements','polls','appeals','settings'];if(teaches())out.splice(6,0,'hours','diagnostic','people');if(admin()&&!out.includes('people'))out.splice(6,0,'people','diagnostic');return out;}
function shell(){const pages=allowedPages();$('#nav').innerHTML=pages.map(k=>'<a href="#'+k+'" class="'+(k===currentPage?'active':'')+'"><span class="nav-icon">'+pageNames[k][2]+'</span><span class="nav-text">'+(k==='grades'&&student()?'Мои оценки':pageNames[k][0])+'</span></a>').join('');$('#crumb').textContent=pageNames[currentPage][0];$('#page-title').textContent=pageNames[currentPage][1];$('#role-label').textContent=roles[me.membership.role];$('#page-desc').textContent=me.institution.name+' · '+({school:'Школа',college:'Колледж',university:'Университет'}[me.institution.type]);$('#institution-badge').innerHTML='<span class="school-icon">⌂</span><div>'+esc(me.institution.name)+'<small>'+roles[me.membership.role]+'</small></div>';$('#profile').innerHTML=avatar()+'<div>'+esc(me.user.name)+'<small>Настройки и сеансы</small></div>';$('#logout').hidden=false;}
async function render(){if(!active()){if(me?.user)await registrationView();return;}clearInterval(chatTimer);const ticket=++sequence;const route=location.hash.slice(1).split('/');currentPage=allowedPages().includes(route[0])?route[0]:'home';if(route[0]==='chats')activeChat=route[1]||'';shell();$('#content').innerHTML='<div class="loading">Загружаем раздел…</div>';try{const html=await views[currentPage]();if(ticket!==sequence)return;$('#content').innerHTML=html;$('#content').className='page-enter';bindPage();updateNotifications();}catch(e){if(ticket===sequence)showError(e.message);} }
function toolbar(subjects=[],period=false){if(!groups().some(g=>g.id===selectedGroup))selectedGroup=groups()[0]?.id||'';return'<div class="portal-filters">'+select(me.institution.type==='school'?'Класс':'Группа','view-group',groups().length?groups().map(g=>[g.id,g.name]):[['','Нет доступных групп']],selectedGroup)+(subjects.length?select('Предмет','view-subject',[['all','Все предметы'],...subjects.map(s=>[s,s])],selectedSubject):'')+(period?select('Период','view-period',[['week','Неделя'],['month','Месяц'],['term',me.institution.config.term_label],['year','Учебный год']],periodKind):'')+'</div>';}
async function recordList(kind){const result=[];let cursor=null;do{const out=await api('/records?kind='+kind+(cursor?'&cursor='+encodeURIComponent(cursor):''));result.push(...out.records);cursor=out.next_cursor;}while(cursor);return result;}
function groupRecords(rs){return rs.filter(r=>!selectedGroup||r.group_id===selectedGroup);}
function canEdit(r){if(['grade','lesson','homework','remark','hours','diagnostic'].includes(r.kind))return me.assignments.some(a=>a.group_id===r.group_id&&a.subject===r.subject);if(['announcement','poll'].includes(r.kind))return admin()||r.group_id&&me.assignments.some(a=>a.group_id===r.group_id);if(r.kind==='achievement')return r.owner_id===me.user.id;return false;}
function recordActions(r){return canEdit(r)?'<div class="row-actions"><button class="text-link" data-edit-record="'+r.id+'">Изменить</button>'+(!['poll','appeal'].includes(r.kind)?'<button class="text-link danger" data-delete-record="'+r.id+'">Удалить</button>':'')+'</div>':'';}
const views={home:homeView,grades:gradesView,schedule:()=>simpleView('lesson'),homework:()=>simpleView('homework'),remarks:()=>simpleView('remark'),hours:()=>simpleView('hours'),diagnostic:diagnosticView,people:peopleView,announcements:()=>feedView('announcement'),achievements:()=>feedView('achievement'),polls:pollsView,appeals:appealsView,chats:chatsView,settings:settingsView,ranking:rankingView};
async function homeView(){const [grades,news,hw,apps]=await Promise.all([recordList('grade'),recordList('announcement'),recordList('homework'),admin()?api('/admin/applications'):Promise.resolve({applications:[]})]);const mine=grades.filter(g=>g.target_id===me.user.id);return'<div class="cabinet-hero"><div><div class="eyebrow">ВАШЕ УЧЕБНОЕ ПРОСТРАНСТВО</div><h2>Здравствуйте, '+esc(me.user.name)+'!</h2><p>Результаты, общение и важные решения связаны с вашей учётной записью.</p><span class="hero-pill">'+esc(me.institution.name)+' · '+roles[me.membership.role]+'</span></div><div class="hero-orbit"><span>✦</span></div></div><div class="stats">'+[[student()?mine.length:grades.length,student()?'Моих оценок':'Доступных оценок'],[groups().length,me.institution.type==='school'?'Доступных классов':'Доступных групп'],[hw.length,'Домашних заданий'],[admin()?apps.applications.length:news.filter(n=>n.unread).length,admin()?'Заявок на доступ':'Непрочитанных объявлений']].map(([v,l])=>'<article class="stat"><div class="stat-top">'+l+'</div><div class="stat-number"><strong>'+v+'</strong></div></article>').join('')+'</div><div class="quick-actions"><button data-page="grades">▤ <b>'+(student()?'Мои оценки':'Журнал')+'</b><span>Результаты и графики →</span></button><button data-page="chats">◌ <b>Чаты</b><span>Учитесь вместе →</span></button><button data-page="achievements">✦ <b>Достижения</b><span>Ваш путь и результаты →</span></button></div>'+panel('Последние объявления','Только доступная вам аудитория',news.slice(0,3).map(n=>feedCard(n)).join('')||empty('Объявлений пока нет.'))+(admin()&&apps.applications.length?'<div class="callout section-gap">Ожидают проверки: '+apps.applications.length+' заявок. '+button('Открыть управление доступом','home-apps')+'</div>':'');}
async function gradesView(){currentRecords=await recordList('grade');const names=[...new Set(currentRecords.map(g=>g.subject))];const base=currentRecords.filter(g=>(!selectedGroup||g.group_id===selectedGroup)&&(selectedSubject==='all'||g.subject===selectedSubject));const range=GradeMath.period(periodKind,me.institution.config,today());const a=GradeMath.analysis(base,range,me.institution.config.scale),gs=a.current;const status=a.difference===null?'Нет сравнения':Math.abs(a.difference)<1e-9?'Без изменений':a.difference>0?'Улучшение':'Снижение';const summary=student()?'<div class="growth-card"><div><span class="eyebrow">'+status.toUpperCase()+'</span><h2>'+f(a.before)+' → '+f(a.now)+' <small>из '+me.institution.config.scale+'</small></h2><p>'+(a.reason?esc(a.reason):'Разница: '+(a.difference>0?'+':'')+f(a.difference)+' балла · относительное изменение '+(a.relative>0?'+':'')+f(a.relative)+'%')+'</p><span class="small-note">'+date(range.previousStart)+' — '+date(range.previousEnd)+' ('+a.previous.length+' оценок) ↔ '+date(range.start)+' — '+date(range.end)+' ('+gs.length+' оценок). Средние приведены к шкале учреждения.</span></div><span class="growth-symbol">'+(a.difference>0?'↗':a.difference<0?'↘':'—')+'</span></div>':'<div class="callout">Показаны оценки, доступные по вашим назначениям. Анализ индивидуального роста находится в ученическом кабинете; графики ниже описывают текущую выборку.</div>';return toolbar(names,true)+'<div class="section-bar"><span class="section-note">'+(student()?'Только мои оценки':'Журнал назначенных предметов')+'</span>'+(teaches()?button('＋ Поставить оценку','new-grade',true):'')+'</div>'+summary+'<div class="subject-tabs">'+[['table','Таблица'],['line','Линейный'],['columns','Столбцы'],['radar','Радар'],['donut','Кольцевая']].map(([k,l])=>'<button data-chart="'+k+'" class="'+(chartType===k?'selected':'')+'">'+l+'</button>').join('')+'</div>'+panel('Результаты за период',date(range.start)+' — '+date(range.end),!gs.length?empty('За этот период оценок нет. Измените период или предмет.'):chartType==='table'?gradeTable(gs):EduCharts[chartType](gs,me.institution.config.scale)+'<p class="small-note">Шкала графиков: '+me.institution.config.scale+' баллов; кольцевая диаграмма показывает исходные оценки. Наведите на точку или столбец для подробностей. Таблица содержит все значения.</p>');}
function gradeTable(gs){return'<div class="table-wrap"><table><thead><tr><th>Дата</th>'+(!student()?'<th>Ученик</th>':'')+'<th>Предмет / работа</th><th>Оценка</th><th>Преподаватель</th><th>Комментарий</th><th>История / действия</th></tr></thead><tbody>'+gs.slice().sort((a,b)=>b.data.date.localeCompare(a.data.date)).map(g=>'<tr><td>'+date(g.data.date)+'</td>'+(!student()?'<td>'+esc(g.targetName||g.target_id.slice(0,8))+'</td>':'')+'<td>'+esc(g.subject)+'<small>'+esc(g.data.title)+'</small></td><td><span class="grade-pill">'+g.data.score+' / '+g.data.max+'</span></td><td>'+esc(g.author)+'</td><td class="wrap-cell">'+esc(g.data.comment)+'</td><td><button class="text-link" data-history="'+g.id+'">История</button>'+recordActions(g)+'</td></tr>').join('')+'</tbody></table></div>';}
async function simpleView(kind){currentRecords=await recordList(kind);const list=groupRecords(currentRecords);let names=[...new Set([...subjectList(),...list.map(r=>r.subject)])];const filtered=list.filter(r=>selectedSubject==='all'||r.subject===selectedSubject);const done=kind==='homework'?(await api('/homework-done')).done:[];return toolbar(names)+'<div class="section-bar"><span class="section-note">'+pageNames[currentPage][0]+'</span>'+(teaches()?button('＋ '+({lesson:'Занятие',homework:'Задание',remark:'Сообщение',hours:'План'}[kind]),'new-simple',true):'')+'</div>'+(!filtered.length?panel('Пока нет записей','Данные добавляются преподавателем',empty('Выберите доступную группу или дождитесь новых записей.')):filtered.map(r=>{const d=r.data;let content;if(kind==='lesson')content='<h3>'+['','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'][d.day]+' · '+esc(d.start)+' — '+esc(d.end)+'</h3><p>'+esc(d.room)+'</p>';if(kind==='homework')content='<h3>'+esc(d.title)+'</h3><p>'+esc(d.description)+'</p><span class="due-date">Срок: '+date(d.due)+'</span>'+(student()?'<button class="button wide" data-homework-done="'+r.id+'" data-is-done="'+done.includes(r.id)+'">'+(done.includes(r.id)?'✓ Выполнено · отменить':'Отметить выполненным')+'</button>':'');if(kind==='remark')content='<span class="badge '+(d.kind==='praise'?'green':'')+'">'+(d.kind==='praise'?'Похвала':'Замечание')+'</span><p>'+esc(d.text)+'</p>';if(kind==='hours')content='<h3>Всего '+d.budget+' часов</h3><div class="table-wrap"><table><thead><tr><th>Тема</th><th>Часы</th></tr></thead><tbody>'+d.rows.map(t=>'<tr><td>'+esc(t.name)+'</td><td>'+t.hours+'</td></tr>').join('')+'</tbody></table></div>';return'<article class="record-card"><div class="section-bar"><span class="badge green">'+esc(r.subject)+'</span><span class="due-date">'+esc(r.author)+'</span></div>'+content+attachments(r)+recordActions(r)+'</article>';}).join(''));}
function audience(r){return r.group_id?groups().find(g=>g.id===r.group_id)?.name||'Назначенная группа':'Всё учреждение';}
function feedCard(r){const d=r.data;return'<article class="record-card '+(r.unread?'unread':'')+'"><div class="section-bar"><span class="badge '+(d.pinned||d.verified?'green':'')+'">'+(r.kind==='achievement'?(d.verified?'✓ Подтверждено':'Не подтверждено'):(d.pinned?'⚑ Закреплено':r.unread?'Новое':'Объявление'))+'</span><small>'+date(r.created_at)+'</small></div><h3>'+esc(d.title)+'</h3><p>'+esc(d.text||d.description||'')+'</p>'+(r.kind==='achievement'?'<p class="small-note">'+esc(d.category)+' · '+date(d.date)+' · '+esc(d.level||'')+' · '+esc(d.result||'')+'</p>'+(d.url?'<a class="text-link" href="'+esc(d.url)+'" target="_blank" rel="noopener">Сертификат / ссылка ↗</a>':''):'<p class="small-note">'+esc(r.author)+' · '+esc(audience(r))+'</p>')+attachments(r)+'<div class="record-bottom">'+recordActions(r)+(r.unread&&r.kind==='announcement'?'<button class="text-link" data-read="'+r.id+'">Отметить прочитанным</button>':'')+(r.kind==='achievement'&&!d.verified&&(admin()||me.assignments.some(a=>a.group_id===r.group_id))?'<button class="button" data-verify="'+r.id+'">Подтвердить достижение</button>':'')+'</div></article>';}
async function feedView(kind){currentRecords=await recordList(kind);const sorted=currentRecords.slice().sort((a,b)=>Number(!!b.data.pinned)-Number(!!a.data.pinned)||b.created_at.localeCompare(a.created_at));return'<div class="section-bar"><span class="section-note">'+(kind==='announcement'?'Лента вашего учреждения и групп':'Личные достижения и их подтверждение')+'</span>'+((kind==='achievement'&&student())||(kind==='announcement'&&(admin()||teaches()))?button('＋ '+(kind==='achievement'?'Добавить достижение':'Опубликовать'),'new-feed',true):'')+'</div>'+(sorted.map(feedCard).join('')||empty('Записей пока нет.'));}
async function pollsView(){currentRecords=await recordList('poll');pollResults={};for(const p of currentRecords)pollResults[p.id]=await api('/polls/'+p.id+'/results');return'<div class="section-bar"><span class="section-note">Один пользователь — один голос</span>'+(admin()||teaches()?button('＋ Создать опрос','new-poll',true):'')+'</div>'+currentRecords.map(p=>{const d=p.data,result=pollResults[p.id],total=result.totals.reduce((s,t)=>s+t.total,0),ended=new Date(d.ends_at)<=new Date();return'<article class="record-card"><div class="section-bar"><span class="badge green">'+(d.anonymous?'Анонимный опрос':'Опрос · общие результаты')+'</span><span class="due-date">До '+date(d.ends_at)+'</span></div><h3>'+esc(d.question)+'</h3><p class="small-note">'+esc(p.author)+' · '+esc(audience(p))+'</p>'+d.options.map(o=>{const n=result.totals.find(t=>t.option_id===o.id)?.total||0;return'<div class="poll-option"><div><span>'+esc(o.text)+'</span><b>'+n+' · '+f(total?n/total*100:0,1)+'%</b></div><div class="progress"><span style="width:'+(total?n/total*100:0)+'%"></span></div>'+(!result.voted&&!ended?'<button class="button" data-vote="'+p.id+'" data-option="'+o.id+'">Выбрать</button>':'')+'</div>';}).join('')+'<p class="small-note">Всего голосов: '+total+' · '+(ended?'Завершён':result.voted?'Ваш голос принят':'Голосование открыто')+'. '+(d.anonymous?'Автору и участникам доступны только общие результаты.':'Индивидуальные ответы в интерфейсе не публикуются.')+'</p></article>';}).join('')+(!currentRecords.length?empty('Активных и завершённых опросов пока нет.'): '');}
const statusNames={sent:'Отправлено',review:'В рассмотрении',resolved:'Решено'};
async function appealsView(){currentRecords=await recordList('appeal');return'<div class="callout">Личная переписка: доступ есть только у автора и выбранного получателя. Обращения не публикуются в чатах или ленте.</div><div class="section-bar"><span class="section-note">Мои обращения'+(['director','deputy'].includes(me.membership.role)?' и личные входящие':'')+'</span>'+button('＋ Создать обращение','new-appeal',true)+'</div>'+currentRecords.map(r=>'<article class="record-card '+(r.unread?'unread':'')+'"><div class="section-bar"><span class="badge '+(r.data.status==='resolved'?'green':'')+'">'+statusNames[r.data.status]+'</span><small>'+date(r.updated_at)+'</small></div><h3>'+esc(r.data.title)+'</h3><p>'+esc(r.data.text.slice(0,250))+'</p><p class="small-note">'+(r.target_id===me.user.id?'Личное входящее · '+esc(r.author):'Ваше обращение')+' · Ответов: '+(r.data.replies||[]).length+'</p><button class="button" data-open-appeal="'+r.id+'">Открыть переписку'+(r.unread?' · новое':'')+'</button></article>').join('')+(!currentRecords.length?empty('Обращений пока нет.'): '');}
async function openAppeal(id){const r=(await api('/records/'+id)).record;await api('/read','POST',{id});const d=r.data;modal(esc(d.title),'<div class="callout">'+esc(d.text)+'</div>'+attachments(r)+'<div class="appeal-replies">'+(d.replies||[]).map(m=>'<div class="message"><b>'+esc(m.author)+'</b><small>'+date(m.at)+'</small><p>'+esc(m.text)+'</p></div>').join('')+'</div><form id="reply-form" class="record-form">'+(r.target_id===me.user.id?select('Статус','status',Object.entries(statusNames),d.status):'<input type="hidden" name="status" value="'+d.status+'">')+textarea('Ответ','reply','','')+'<div id="reply-error" class="form-feedback full-field"></div><button class="button primary">Отправить ответ / сохранить статус</button></form>');$('#reply-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const b=Object.fromEntries(new FormData(e.target));await api('/records/'+id,'PATCH',{data:{status:b.status},reply:b.reply});$('#modal').close();await render();toast('Ответ сохранён и доступен получателю');});};}
async function chatsView(){const data=await api('/chats');currentRecords=data.chats;return'<div class="section-bar"><span class="section-note">История демочатов сохраняется в этом браузере</span>'+button('＋ Новый чат','new-chat',true)+'</div><div class="chat-layout"><aside class="chat-list">'+data.chats.map(c=>'<button data-open-chat="'+c.id+'" class="'+(c.id===activeChat?'active':'')+'"><b>'+esc(c.data.title)+'</b><small>'+(c.data.type==='personal'?'Личный чат':'Предметный чат')+'</small>'+(c.unreadCount?'<span class="nav-count">'+c.unreadCount+'</span>':'')+'</button>').join('')+(!data.chats.length?empty('Чатов пока нет.'): '')+'</aside><section class="panel chat-main"><div id="chat-header" class="panel-head"><h2>Выберите чат</h2></div><div id="chat-messages" aria-live="polite">'+empty('Обсудите занятие с группой или напишите личное сообщение.')+'</div><form id="send-message" hidden><label class="sr-only" for="message-text">Сообщение</label><textarea id="message-text" maxlength="4000" placeholder="Напишите сообщение…" required></textarea><button class="button primary">Отправить</button></form></section></div>';}
async function refreshChat(initial=false){if(!activeChat)return;const selected=activeChat;try{const res=await api('/messages?chat_id='+encodeURIComponent(selected));if(selected!==activeChat||currentPage!=='chats')return;$('#chat-header').innerHTML='<div><h2>'+esc(res.chat.data.title)+'</h2><details><summary>Участники · '+res.participants.length+'</summary><p>'+res.participants.map(p=>esc(p.name)).join(', ')+'</p></details></div>';chatBefore=res.next;$('#chat-messages').innerHTML=(res.next?button('Загрузить более ранние','older-messages'):'')+res.messages.map(messageHTML).join('');$('#send-message').hidden=false;$('#send-message').onsubmit=e=>{e.preventDefault();safely(async()=>{const input=$('#message-text');const text=input.value;input.disabled=true;try{await api('/messages','POST',{chat_id:selected,text});input.value='';await refreshChat();}finally{input.disabled=false;input.focus();}});};if($('#older-messages'))$('#older-messages').onclick=loadOlderMessages;if(initial)$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;await api('/read','POST',{id:selected});}catch(e){if($('#chat-messages'))$('#chat-messages').innerHTML='<div class="error-list">'+esc(e.message)+'</div>';}}
function messageHTML(m){return'<article class="message '+(m.owner_id===me.user.id?'mine':'')+'"><b>'+esc(m.author)+'</b><small>'+date(m.created_at)+'</small><p>'+esc(m.data.text)+'</p></article>';}
async function loadOlderMessages(){if(!chatBefore)return;const res=await api('/messages?chat_id='+activeChat+'&before='+chatBefore);chatBefore=res.next;$('#older-messages')?.remove();$('#chat-messages').insertAdjacentHTML('afterbegin',(res.next?button('Загрузить более ранние','older-messages'):'')+res.messages.map(messageHTML).join(''));if($('#older-messages'))$('#older-messages').onclick=loadOlderMessages;}
async function newChat(){directory=(await api('/contacts')).people;const subjectOptions=subjectList();formModal('Открыть чат',select('Тип','type',[['subject','Предметный чат'],['personal','Личное сообщение']])+select('Группа','group_id',groups().map(g=>[g.id,g.name]),selectedGroup)+field('Предмет (для предметного чата)','subject',subjectOptions[0]||'Математика')+select('Получатель (для личного чата)','user_id',[['','Выберите человека'],...directory.map(p=>[p.id,p.name+' · '+roles[p.role]])]),async b=>{const out=await api('/chats/open','POST',b);activeChat=out.id;location.hash='chats/'+out.id;});}
async function rankingView(){if(!selectedGroup)return toolbar()+empty('Сначала нужно вступить в группу или получить назначение.');const result=await api('/ranking?group_id='+selectedGroup),ss=[...new Set(result.people.flatMap(p=>Object.keys(p.subjects)))];const ps=result.people.map(p=>({...p,value:selectedSubject==='all'?p.average:p.subjects[selectedSubject]??null})).sort((a,b)=>a.value===null?1:b.value===null?-1:b.value-a.value);let prior=null,rank=0;return toolbar(ss)+'<div class="callout">Рейтинг внутри группы по нормированным оценкам. Общий результат — среднее по предметам с равным весом. При разном охвате предметов результаты требуют осторожной интерпретации. Без оценок места нет.</div>'+panel('Рейтинг группы',result.people.length+' участников','<div class="table-wrap"><table><thead><tr><th>Место</th><th>Участник</th>'+ss.map(s=>'<th>'+esc(s)+'</th>').join('')+'<th>Результат</th></tr></thead><tbody>'+ps.map((p,i)=>{const v=p.value===null?null:Math.round(p.value*100)/100;if(v!==null&&v!==prior)rank=i+1;prior=v;return'<tr class="'+(p.id===me.user.id?'my-row':'')+'"><td>'+ (v===null?'—':rank)+'</td><td>'+esc(p.name)+(p.id===me.user.id?' · Вы':'')+'</td>'+ss.map(s=>'<td>'+f(p.subjects[s]??null)+'%</td>').join('')+'<td>'+f(v)+(v===null?'':'%')+'</td></tr>';}).join('')+'</tbody></table></div>');}
async function peopleView(){let html=toolbar()+'<div class="section-bar"><span>Состав выбранной группы</span>'+button('Создать приглашение','new-invite',true)+(admin()?button('＋ Создать '+(me.institution.type==='school'?'класс':'группу'),'new-group'):'')+'</div>';if(selectedGroup){people=(await api('/people?group_id='+selectedGroup)).people;html+=panel('Участники','Всего: '+people.length+' · Подтверждены: '+people.filter(p=>p.status==='active').length,field('Поиск по имени','people-search','','search','id="people-search" placeholder="Начните вводить имя"')+'<div class="table-wrap"><table><thead><tr><th>ФИО</th><th>Статус</th><th>Действия</th></tr></thead><tbody>'+people.map(p=>'<tr data-person-name="'+esc(p.name.toLowerCase())+'"><td>'+esc(p.name)+'</td><td>'+({active:'В группе',pending:'Ожидает вступления',removed:'Удалён из состава'}[p.status]||p.status)+'</td><td class="row-actions">'+(p.status==='pending'?'<button class="text-link" data-enrollment="'+p.enrollment_id+'" data-action="approve">Подтвердить</button>':'')+(p.status==='active'?'<button class="text-link" data-transfer="'+p.enrollment_id+'">Перевести</button><button class="text-link danger" data-enrollment="'+p.enrollment_id+'" data-action="remove">Удалить из состава</button>':'')+'</td></tr>').join('')+'</tbody></table></div>');}else html+=empty('Сначала создайте группу или дождитесь назначения.');if(admin()){const [apps,staff]=await Promise.all([api('/admin/applications'),api('/admin/staff')]);directory=staff.staff;html+='<div class="section-gap">'+panel('Заявки на доступ','Роли выдаются только после подтверждения',apps.applications.map(a=>'<article class="application-card"><b>'+esc(a.name)+'</b><small>'+esc(a.email)+' · '+roles[a.data.role]+'</small><p>Предметы: '+esc(a.data.subjects.join(', ')||'Не преподаёт')+'<br>Группы: '+a.data.groups.map(id=>esc(groups().find(g=>g.id===id)?.name||id)).join(', ')+'</p><button class="button primary" data-application="'+a.id+'" data-action="approve">Подтвердить заявку</button> <button class="button" data-application="'+a.id+'" data-action="reject">Отклонить</button></article>').join('')||empty('Заявок нет.'))+'</div><div class="section-gap">'+panel('Назначения преподавателей','Только указанные предметы и группы доступны для выставления оценок',button('Настроить назначения сотрудника','edit-assignments')+'<div class="table-wrap"><table><thead><tr><th>Сотрудник</th><th>Роль</th><th>Назначения</th></tr></thead><tbody>'+staff.staff.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+roles[p.role]+'</td><td class="wrap-cell">'+staff.assignments.filter(a=>a.user_id===p.id).map(a=>esc(a.subject)+' — '+esc(groups().find(g=>g.id===a.group_id)?.name||'')).join('<br>')+'</td></tr>').join('')+'</tbody></table></div>')+'</div>';}return html;}
